"""Immutable manifest plus seven versioned canonical indicator series. No DDL."""
import json,pathlib,hashlib
ROOT=pathlib.Path(__file__).resolve().parents[2]
p=json.loads((ROOT/'src/data/research/education-income.json').read_text())
raw=json.dumps(p,ensure_ascii=False,separators=(',',':'));key='education_income_v1:'+hashlib.sha256(raw.encode()).hexdigest();assert '$income$' not in raw
print('BEGIN;')
print("DO $persist$ DECLARE k text := '"+key+"'; p jsonb := $income$"+raw+"$income$::jsonb; BEGIN PERFORM pg_advisory_xact_lock(hashtext(k)); IF EXISTS(SELECT 1 FROM public.dataset_meta WHERE id=k AND data<>p) THEN RAISE EXCEPTION 'Immutable income conflict'; END IF; INSERT INTO public.dataset_meta(id,data) VALUES(k,p) ON CONFLICT(id) DO NOTHING; END $persist$;")
series=[('income','tjt-henkiloita','population','Asuntoväestö koulutuksen, iän ja sukupuolen mukaan','henkilöä'),('income','tjt-ekvikturaha_med','household_median','Asuntokunnan rahatulo kulutusyksikköä kohden henkilön koulutuksen mukaan, mediaani','euroa/vuosi, vuoden 2024 rahassa'),('income','hkturaha_med','personal_disposable_median','Henkilökohtainen käytettävissä oleva rahatulo koulutuksen mukaan, mediaani','euroa/vuosi, vuoden 2024 rahassa'),('income','htuotektu_med','factor_income_median','Henkilökohtainen tuotannontekijätulo koulutuksen mukaan, mediaani','euroa/vuosi, vuoden 2024 rahassa'),('wages','koko_psaaja_lkm','fulltime_count','Kokoaikaisten palkansaajien lukumäärä koulutuksen mukaan 2024','henkilöä'),('wages','koko_psaaja_kans_med','wage_median','Kokoaikaisten palkansaajien kokonaisansion mediaani koulutuksen mukaan 2024','euroa/kuukausi'),('wages','koko_psaaja_kans_ka','wage_mean','Kokoaikaisten palkansaajien kokonaisansion keskiarvo koulutuksen mukaan 2024','euroa/kuukausi')]
def lit(s):return "'"+s.replace("'","''")+"'"
for family,measure,suffix,title,unit in series:
 sk='education.income.v20261025.'+suffix;src=p['sources'][0 if family=='income' else 1];url=src['url'];start=2010 if family=='income' else 2024
 metadata=json.dumps(dict(manifest=key,measure=measure,source_request=src,causal_effect_identified=False,known_break_years=[] if family=='income' else [2024]),ensure_ascii=False)
 print('INSERT INTO public.indicator_series(series_key,title,description,source,source_url,unit,geography,frequency,start_year,end_year,data_class,status,theme,published,metadata,quality) VALUES('+','.join([lit(sk),lit(title),lit(p['notes']['real_income' if family=='income' else 'wages']),lit('Tilastokeskus / StatFin'),lit(url),lit(unit),lit('Finland; group_key contains age, sex, education and optional field'),lit('annual'),str(start),'2024',lit('observed'),lit('curated'),lit('Koulutus, työ ja toimeentulo'),'true',lit(metadata)+'::jsonb',lit(json.dumps({'validation':'source_snapshot_checked','causal_effect_identified':False}))+'::jsonb'])+') ON CONFLICT(series_key) DO NOTHING;')
 # Fail on stale or conflicting numerical cells rather than overwriting them.
 common="WITH rows AS (SELECT r, 'age='||(r->>'age')||'|sex='||(r->>'sex')||'|education='||(r->>'education')"+("||'|field='||(r->>'field')" if family=='wages' else '')+" g FROM public.dataset_meta d CROSS JOIN LATERAL jsonb_array_elements(d.data->'"+family+"') r WHERE d.id="+lit(key)+" AND r->>'measure'="+lit(measure)+" AND jsonb_typeof(r->'value')='number') "
 print("DO $check$ BEGIN IF EXISTS("+common+"SELECT 1 FROM rows JOIN public.indicator_values v ON v.series_key="+lit(sk)+" AND v.year=(r->>'year')::integer AND v.group_key=g WHERE v.value IS DISTINCT FROM (r->>'value')::numeric) THEN RAISE EXCEPTION 'Conflicting income cell'; END IF; END $check$;")
 print(common+"INSERT INTO public.indicator_values(series_key,year,group_key,group_label,value,value_kind,validation_status,is_published,source_url,source_version,meta) SELECT "+lit(sk)+",(r->>'year')::integer,g,g,(r->>'value')::numeric,'observed','source_snapshot_checked',true,"+lit(url)+","+lit(src['response_sha256'])+",jsonb_build_object('manifest',"+lit(key)+",'measure',"+lit(measure)+") FROM rows ON CONFLICT(series_key,year,group_key) DO NOTHING;")
print("COMMIT; SELECT count(distinct series_key) series,count(*) observations FROM public.indicator_values WHERE series_key LIKE 'education.income.v20261025.%';")
